    find_current_step() {
      // console.log(this.formDetails.approval_user_list);
      var filteredArray = [];
      this.formDetails.approval_user_list.sort(function (a, b) {
        return a.step_no - b.step_no;
      });
      var rejectedIndex = this.formDetails.approval_user_list.findIndex(obj => obj.approval_status === "REJECTED");
      this.formDetails.approval_user_list.filter((obj, index) => index <= rejectedIndex);
      // console.log(this.formDetails.approval_user_list);
      const completedItem = this.formDetails.approval_user_list.find(item => item.approval_status === "INPROGRESS");
      if (completedItem) {
