            user_email_id: data.user.user_email_id,
            initiate_id: this.formDetails.initiate_id,
            approval_status: val,
            workflow_payload: JSON.stringify(this.formDetails.workflow_payload),
            comments: this.approvalComments,
            forward_user_email_id: val == "FORWARD" ? this.forwardUser : undefined
          }
        }));
        var response = JSON.parse(result.data.workflow_appr_rej);
        this.loading = false;
        this.loading1 = false;
